#include <atomic>

// AI: below section was generated by an AI
/*
  WiFi connection monitor.

  WiFiEvent() (network.cpp) takes no arduino_event_info_t, so it cannot see why a
  connection dropped, and it says nothing at all about a connection that never came up.
  The handler here records the wifi_err_reason_t of every drop: 201 NO_AP_FOUND (SSID not
  visible), 2 AUTH_EXPIRE / 15 4WAY_HANDSHAKE_TIMEOUT / 204 HANDSHAKE_TIMEOUT (visible,
  but authentication did not complete), 8 ASSOC_LEAVE (a deliberate deauthentication),
  205 CONNECTION_FAIL.

  Automatic transmit power, only with WLED_ENABLE_AUTO_TX_POWER. The configured "Max. TX
  power" becomes a ceiling and the level actually used comes from three inputs:

    Signal strength. The path to the router is about as lossy in both directions, so the
    router's RSSI says how much power the board needs to be heard. The level is the
    lowest one that should put the board at TXPOWER_TARGET_AT_ROUTER_DBM at the router.

    Temperature. On the board this was written for, full power stops authenticating once
    the chip is hot, while 11 dBm keeps working (readme.md, "What changed, and why"). From
    TXPOWER_HOT_C the level from signal strength is capped at 11 dBm, until the chip is
    back below TXPOWER_COOL_C.

    Failures. Both of the above are estimates, so repeated AUTH_EXPIRE moves the level:
    first down one step at a time to the lowest, then up from the estimate to the
    ceiling, then back to the estimate. It never settles on a level that does not
    connect, and a level that connects is kept as an offset from the estimate.

  Only AUTH_EXPIRE counts, because it is the one failure that points at the transmitter:
  the router never answered the first frame of the exchange. That is what the hot board
  produced on every attempt. A wrong password fails later, in the four-way handshake
  (15 / 204 -- ESP-IDF Wi-Fi guide, "Wi-Fi Reason code related to wrong password"), by
  which point the router has heard and answered the board, so a handshake timeout leaves
  the power alone and clears the AUTH_EXPIRE count. Not established: what a wrong WPA3
  (SAE) password reports, since SAE checks the password in the authentication frames. If
  that is AUTH_EXPIRE too, the search still cycles instead of sticking. A settings save
  restarts it from the estimate, and each change is a netlog entry.

  Tasks. The event handler runs on the WiFi event task and only records what happened.
  The level is chosen and applied by wifiMonitorLoop() on the loop task, which also
  reviews signal strength and temperature every TXPOWER_REVIEW_MS, connected or not.
*/
static unsigned long lastFailureMs        = 0;
static unsigned long lastAssociatedMs     = 0;
static uint8_t       lastDisconnectReason = 0;
static unsigned long lastDisconnectMs     = 0;

unsigned long wifiLastFailureMs()        { return lastFailureMs; }
unsigned long wifiLastAssociatedMs()     { return lastAssociatedMs; }
uint8_t       wifiLastDisconnectReason() { return lastDisconnectReason; }
unsigned long wifiLastDisconnectMs()     { return lastDisconnectMs; }

#ifdef WLED_ENABLE_AUTO_TX_POWER
// Where the router should hear the board. Derived from the one working point measured:
// 11 dBm at RSSI -62, taking the router to transmit at TXPOWER_ROUTER_DBM. That is about
// 20 dB above what the slowest rates need, which leaves room for the estimate to be wrong.
static constexpr int TXPOWER_TARGET_AT_ROUTER_DBM = -71;
static constexpr int TXPOWER_ROUTER_DBM           = 20;    // assumed; routers do not report it
static constexpr int TXPOWER_RSSI_HYSTERESIS_DB   = 3;     // RSSI wanders by a few dB; smaller moves are ignored
// Between the two temperatures measured: full power worked at 55 C and failed at 70 C.
static constexpr float   TXPOWER_HOT_C            = 65.0f;
static constexpr float   TXPOWER_COOL_C           = 60.0f;
static constexpr uint8_t TXPOWER_HOT_CAP          = WIFI_POWER_11dBm;
static constexpr uint8_t TXPOWER_FAILURES_PER_STEP = 3;    // consecutive AUTH_EXPIRE before trying another level
static constexpr unsigned long TXPOWER_REVIEW_MS  = 10000;

// The levels the driver offers below 20 dBm, as wifi_power_t (quarter dBm), ascending.
static const uint8_t TXPOWER_LEVELS[] = {
  WIFI_POWER_2dBm, WIFI_POWER_5dBm, WIFI_POWER_7dBm, WIFI_POWER_8_5dBm, WIFI_POWER_11dBm, WIFI_POWER_13dBm,
  WIFI_POWER_15dBm, WIFI_POWER_17dBm, WIFI_POWER_18_5dBm, WIFI_POWER_19dBm, WIFI_POWER_19_5dBm
};
static constexpr int TXPOWER_LEVEL_COUNT = sizeof(TXPOWER_LEVELS) / sizeof(TXPOWER_LEVELS[0]);

// Posted by other tasks (WiFi events, the web server saving settings), consumed by the loop task.
static std::atomic<uint8_t> postedAuthExpires{0};
static std::atomic<bool>    postedHandshakeTimeout{false};
static std::atomic<bool>    postedConnected{false};
static std::atomic<bool>    postedReset{false};
static std::atomic<int8_t>  postedRssi{0};          // 0 = none

// Loop task only.
static uint8_t txPowerNow    = 0;      // level in use; 0 = not chosen yet, see wifiTxPower()
static int8_t  routerRssi    = 0;      // the RSSI the level is based on; 0 = unknown
static int8_t  searchOffset  = 0;      // steps away from the estimate that the failure search has moved
static uint8_t authExpires   = 0;      // consecutive AUTH_EXPIRE at the current level
static bool    chipHot       = false;  // the temperature cap is on
static unsigned long lastReviewMs = 0;

// The candidate levels are the table entries below the ceiling, then the ceiling itself,
// so a ceiling that is not in the table (or above it) is still reachable.
static int txPowerTopIndex()
{
  int n = 0;
  while (n < TXPOWER_LEVEL_COUNT && TXPOWER_LEVELS[n] < txPower) n++;
  return n;
}

static uint8_t txPowerAt(int index, int top) { return index >= top ? txPower : TXPOWER_LEVELS[index]; }

// Index of the lowest candidate that is at least `level`, or the ceiling.
static int txPowerIndexFor(int level, int top)
{
  int i = 0;
  while (i < top && TXPOWER_LEVELS[i] < level) i++;
  return i;
}

// The level signal strength and temperature call for, before the failure search.
static int txPowerEstimate(int top)
{
  int index = top;   // no RSSI yet (boot, or settings just saved): the ceiling
  if (routerRssi < 0) {
    const int pathLoss = TXPOWER_ROUTER_DBM - routerRssi;
    index = txPowerIndexFor((TXPOWER_TARGET_AT_ROUTER_DBM + pathLoss) * 4, top);
  }
  #ifdef WLED_HAS_SOC_TEMPERATURE
  const float celsius = socTemperatureRead();   // NaN when unreadable: both comparisons are false and the state holds
  if (celsius >= TXPOWER_HOT_C) chipHot = true;
  else if (celsius <= TXPOWER_COOL_C) chipHot = false;
  if (chipHot) index = min(index, txPowerIndexFor(TXPOWER_HOT_CAP, top));
  #endif
  return index;
}

// The next offset to try: down to the lowest level, then up from the estimate to the
// ceiling, then the estimate again.
static int8_t txPowerNextOffset(int estimate, int top)
{
  if (searchOffset <= 0) {
    if (estimate + searchOffset > 0) return searchOffset - 1;
    return estimate < top ? 1 : 0;
  }
  return estimate + searchOffset < top ? searchOffset + 1 : 0;
}

// Recompute the level from the current inputs and apply it if it changed.
static void txPowerUpdate(bool searchFurther)
{
  const int top      = txPowerTopIndex();
  const int estimate = txPowerEstimate(top);
  if (searchFurther) searchOffset = txPowerNextOffset(estimate, top);
  const uint8_t level = txPowerAt(constrain(estimate + searchOffset, 0, top), top);
  if (level == txPowerNow) return;
  if (txPowerNow == 0 && level == txPower) return;   // nothing known and the answer is the ceiling: wifiTxPower() already says so
  txPowerNow = level;
  WiFi.setTxPower(wifi_power_t(level));   // initConnection() and initAP() apply it again
  netlogAdd(NL_TX_POWER, level, routerRssi);
  DEBUG_PRINTF_P(PSTR("WiFi: TX power set to %u (rssi %d, hot %d, search offset %d).\n"), (unsigned)level, (int)routerRssi, (int)chipHot, (int)searchOffset);
}

// Take a new RSSI reading as the basis for the level, unless it is noise around the
// reading the level is already based on.
static void txPowerNoteRssi(int rssi)
{
  if (rssi >= 0 || rssi <= -120) return;   // the driver reports 0 or a floor value when it has none
  if (routerRssi == 0 || abs(rssi - routerRssi) >= TXPOWER_RSSI_HYSTERESIS_DB) routerRssi = rssi;
}

uint8_t wifiTxPower()
{
  if (txPowerNow) return txPowerNow;
  // Nothing chosen yet (boot, or settings just saved). With no RSSI to go by the estimate
  // is the ceiling, but still capped while the chip is hot, so a hot board does not open
  // with the one level known to fail.
  const int top = txPowerTopIndex();
  return txPowerAt(txPowerEstimate(top), top);
}

void wifiTxPowerReset() { postedReset = true; }
#else
uint8_t wifiTxPower()      { return txPower; }
void    wifiTxPowerReset() {}
#endif // WLED_ENABLE_AUTO_TX_POWER

void wifiMonitorLoop()
{
  #ifdef WLED_ENABLE_AUTO_TX_POWER
  bool review = false, readRssi = false, searchFurther = false;

  if (postedReset.exchange(false)) {   // settings loaded or saved: start again from the estimate
    txPowerNow = 0; routerRssi = 0; searchOffset = 0; authExpires = 0;
    review = readRssi = true;
  }
  const int8_t rssi = postedRssi.exchange(0);
  if (rssi) { txPowerNoteRssi(rssi); review = true; }

  // AUTH_EXPIRE: the router did not answer at all, the one failure that points at our
  // transmitter. A handshake timeout means it answered and the key exchange failed: a
  // wrong password, not the radio. Anything else says nothing either way.
  const uint8_t expires = postedAuthExpires.exchange(0);
  if (expires) {
    authExpires += expires;
    if (authExpires >= TXPOWER_FAILURES_PER_STEP) { authExpires = 0; searchFurther = true; }
    review = true;
  }
  if (postedHandshakeTimeout.exchange(false)) authExpires = 0;
  if (postedConnected.exchange(false)) { authExpires = 0; review = readRssi = true; }

  const unsigned long now = millis();
  if (now - lastReviewMs >= TXPOWER_REVIEW_MS) review = readRssi = true;
  if (!review) return;
  lastReviewMs = now;
  if (readRssi && WLEDNetwork.isWiFiUp()) txPowerNoteRssi(WiFi.RSSI());   // the live reading while connected
  txPowerUpdate(searchFurther);
  #endif
}

#ifdef WLED_AP_RESCUE
// A rescue build keeps WiFi and Ethernet up together, so wasConnected and interfacesInited
// -- set by either interface -- are true with Ethernet up while WiFi has never connected.
// Upstream's drop handling in WiFiEvent() would then treat every failed attempt (one every
// ~2.5 s with the network absent) as a drop: forcing a reconnect, rebinding mDNS/OTA and
// scanning continuously. So a drop counts only if WiFi itself had an address.
static bool wifiHadAddress = false;

static void handleWifiDrop()
{
  if (!(wifiHadAddress && wasConnected && interfacesInited)) return;
  wifiHadAddress = false;
  DEBUG_PRINTF_P(PSTR("WiFi-E: Disconnected! @ %lus\n"), millis()/1000);
  if (multiWiFi.size() > 1 && WiFi.scanComplete() >= 0) findWiFi(true);   // reinit WiFi scan
  // Reconnect on the next loop; a failing network cannot loop here because the gate above
  // needs a successful connection first.
  forceReconnect = true;
  interfacesInited = false;
}
#endif

// WiFi event task. Records only; see "Tasks" above.
static void wifiMonitorEvent(arduino_event_id_t event, arduino_event_info_t info)
{
  switch (event) {
    case ARDUINO_EVENT_WIFI_STA_CONNECTED:
      lastAssociatedMs = millis();
      break;
    case ARDUINO_EVENT_WIFI_STA_GOT_IP:
      #ifdef WLED_ENABLE_AUTO_TX_POWER
      postedConnected = true;
      #endif
      #ifdef WLED_AP_RESCUE
      wifiHadAddress = true;
      #endif
      break;
    case ARDUINO_EVENT_WIFI_STA_DISCONNECTED: {
      #ifdef WLED_AP_RESCUE
      handleWifiDrop();
      #endif
      const uint8_t reason = info.wifi_sta_disconnected.reason;
      const int8_t  rssi   = info.wifi_sta_disconnected.rssi;
      DEBUG_PRINTF_P(PSTR("WiFi-E: STA disconnected, reason %u, rssi %d @ %lus\n"), (unsigned)reason, (int)rssi, millis()/1000);
      if (reason == WIFI_REASON_STA_LEAVING) break;   // our own disconnect() at the start of every attempt
      lastDisconnectReason = reason;
      lastDisconnectMs = millis();
      netlogAdd(NL_STA_DISCONNECTED, reason, rssi);
      if (reason == WIFI_REASON_ASSOC_LEAVE) break;   // a deliberate leave is not a verdict on the attempt
      lastFailureMs = millis();
      #ifdef WLED_ENABLE_AUTO_TX_POWER
      if (rssi < 0 && rssi > -120) postedRssi = rssi;
      if (reason == WIFI_REASON_AUTH_EXPIRE) postedAuthExpires++;
      else if (reason == WIFI_REASON_4WAY_HANDSHAKE_TIMEOUT || reason == WIFI_REASON_HANDSHAKE_TIMEOUT) postedHandshakeTimeout = true;
      #endif
      break;
    }
    default:
      break;
  }
}

void wifiMonitorInit()
{
  WiFi.onEvent(wifiMonitorEvent);
}
